    """把域名写入 out；offsets 记录已出现的标签边界（后缀 -> 最小偏移）。

    log 非 None 时，实际新插入 offsets 的 (位置, 后缀) 追加其中，供
    RRset 截断按起始偏移回滚压缩表。
    """
    match = 0
    target = None
    for i in range(len(labels)):
        suffix = tuple(labels[i:])
        if suffix in offsets:
            match = len(labels) - i
            target = offsets[suffix]
            break
    stop = len(labels) - match
